package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// TestGenGoTargetHygiene drives `strictspec gen` for a schema with a go target,
// then asserts the generated file lands chmod 444, carries the pinned
// generated-file marker, and is registered in .gitattributes. A follow-up
// `check` must report fresh, and must catch drift in the generated file.
func TestGenGoTargetHygiene(t *testing.T) {
	dir := t.TempDir()
	schemasDir := filepath.Join(dir, "schemas")
	if err := os.MkdirAll(filepath.Join(dir, "gen"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(schemasDir, 0o755); err != nil {
		t.Fatal(err)
	}
	// shared-canvas imports types-geometry, so it exercises the imported-file
	// embedding path.
	copyFile(t, filepath.Join(fixturesSchemas(t), "shared-canvas.toml"), filepath.Join(schemasDir, "shared-canvas.toml"))
	copyFile(t, filepath.Join(fixturesSchemas(t), "types-geometry.toml"), filepath.Join(schemasDir, "types-geometry.toml"))

	manifest := filepath.Join(dir, "strictspec.toml")
	writeFile(t, manifest, `format_version = 1
[[schemas]]
path = "schemas/shared-canvas.toml"
  [[schemas.targets]]
  lang = "go"
  output = "gen/canvas_gen.go"
  package = "canvas"
`)

	if r := newApp().Test([]string{"gen", "--manifest", manifest}); r.ExitCode != 0 {
		t.Fatalf("gen exit = %d: %s", r.ExitCode, r.Stderr)
	}

	genPath := filepath.Join(dir, "gen", "canvas_gen.go")
	info, err := os.Stat(genPath)
	if err != nil {
		t.Fatalf("generated file missing: %v", err)
	}
	if info.Mode().Perm() != 0o444 {
		t.Errorf("%s mode = %v, want 0444 (chmod 444 hygiene)", genPath, info.Mode().Perm())
	}
	src, _ := os.ReadFile(genPath)
	if !strings.Contains(string(src), "// Code generated by strictspec. DO NOT EDIT.") {
		t.Errorf("%s missing the generated-file marker", genPath)
	}

	// .gitattributes must register the generated path (LF + linguist-generated).
	ga, err := os.ReadFile(filepath.Join(dir, ".gitattributes"))
	if err != nil {
		t.Fatalf(".gitattributes missing: %v", err)
	}
	if !strings.Contains(string(ga), "gen/canvas_gen.go") {
		t.Errorf(".gitattributes missing entry for gen/canvas_gen.go\n%s", ga)
	}

	if r := newApp().Test([]string{"check", "--manifest", manifest}); r.ExitCode != 0 {
		t.Fatalf("check (fresh) exit = %d: %s", r.ExitCode, r.Stderr)
	}

	_ = os.Chmod(genPath, 0o644)
	writeFile(t, genPath, string(src)+"\n// tampered\n")
	_ = os.Chmod(genPath, 0o444)
	if r := newApp().Test([]string{"check", "--manifest", manifest}); r.ExitCode == 0 {
		t.Fatal("check must fail on drift in the generated file")
	}
}

const tinySchema = `name = "Tiny"
meta_version = 1
format_version = 1
document_syntax = "json"
role = "schema"
root = "Tiny"

[types.Tiny]
type = "record"

[types.Tiny.fields.n]
type = "integer"
`

// TestManifestRefusesRemovedTargets asserts that a manifest naming the removed
// python or ts generation target is refused by gen and by check, with a message
// naming go as the only generation target, and that the fix the message names
// (declaring the go target instead) clears the refusal.
func TestManifestRefusesRemovedTargets(t *testing.T) {
	for _, lang := range []string{"python", "ts"} {
		t.Run(lang, func(t *testing.T) {
			dir := t.TempDir()
			writeFile(t, filepath.Join(dir, "tiny.schema.toml"), tinySchema)
			manifest := filepath.Join(dir, "strictspec.toml")
			writeFile(t, manifest, `format_version = 1
[[schemas]]
path = "tiny.schema.toml"
  [[schemas.targets]]
  lang = "`+lang+`"
  output = "tiny.generated"
`)
			want := `lang = "` + lang + `": the ` + lang + ` generation target was removed; the only generation target is "go"`
			for _, cmd := range []string{"gen", "check"} {
				r := newApp().Test([]string{cmd, "--manifest", manifest})
				if r.ExitCode == 0 {
					t.Fatalf("%s with a %s target must be refused", cmd, lang)
				}
				if !strings.Contains(r.Stderr, want) {
					t.Errorf("%s: expected %q, got:\n%s", cmd, want, r.Stderr)
				}
			}
			if _, err := os.Stat(filepath.Join(dir, "tiny.generated")); err == nil {
				t.Fatal("a refused gen must write nothing")
			}

			writeFile(t, manifest, `format_version = 1
[[schemas]]
path = "tiny.schema.toml"
  [[schemas.targets]]
  lang = "go"
  output = "tiny_gen.go"
`)
			if r := newApp().Test([]string{"gen", "--manifest", manifest}); r.ExitCode != 0 {
				t.Fatalf("gen after declaring the go target: exit %d: %s", r.ExitCode, r.Stderr)
			}
			if r := newApp().Test([]string{"check", "--manifest", manifest}); r.ExitCode != 0 {
				t.Fatalf("check after declaring the go target: exit %d: %s", r.ExitCode, r.Stderr)
			}
		})
	}
}

// TestGenUnknownTargetIsHardError asserts an unknown target lang is a hard error.
func TestGenUnknownTargetIsHardError(t *testing.T) {
	dir := t.TempDir()
	schema := filepath.Join(dir, "tiny.schema.toml")
	writeFile(t, schema, `name = "Tiny"
meta_version = 1
format_version = 1
document_syntax = "json"
role = "schema"
root = "Tiny"

[types.Tiny]
type = "record"

[types.Tiny.fields.n]
type = "integer"
`)
	manifest := filepath.Join(dir, "strictspec.toml")
	writeFile(t, manifest, `format_version = 1
[[schemas]]
path = "tiny.schema.toml"
  [[schemas.targets]]
  lang = "rust"
  output = "tiny.rs"
`)
	r := newApp().Test([]string{"gen", "--manifest", manifest})
	if r.ExitCode == 0 {
		t.Fatal("gen with an unknown target lang must hard-error")
	}
	if want := `lang = "rust" is not a generation target; the only generation target is "go"`; !strings.Contains(r.Stderr, want) {
		t.Errorf("expected %q, got:\n%s", want, r.Stderr)
	}
}
